import { useState } from 'react';
import './styles.css';

interface Candidate {
  id: number;
  name: string;
  experience: number;
  skills: number;
  group: 'A' | 'B';
}

interface TrainingPerson {
  group: 'A' | 'B';
  hired: boolean;
}

const testCandidates: Candidate[] = [
  { id: 1, name: 'Alex', experience: 5, skills: 85, group: 'A' },
  { id: 2, name: 'Jordan', experience: 4, skills: 90, group: 'B' },
  { id: 3, name: 'Sam', experience: 6, skills: 80, group: 'A' },
  { id: 4, name: 'Taylor', experience: 3, skills: 95, group: 'B' },
  { id: 5, name: 'Morgan', experience: 7, skills: 75, group: 'A' },
  { id: 6, name: 'Casey', experience: 5, skills: 88, group: 'B' },
];

type DatasetType = 'biased' | 'balanced';

export default function App() {
  const [dataset, setDataset] = useState<DatasetType | null>(null);
  const [isTraining, setIsTraining] = useState(false);
  const [isTrained, setIsTrained] = useState(false);
  const [results, setResults] = useState<Record<number, boolean>>({});
  const [showWhy, setShowWhy] = useState(false);
  const [comparisonMode, setComparisonMode] = useState(false);
  const [biasedResults, setBiasedResults] = useState<Record<number, boolean>>({});
  const [balancedResults, setBalancedResults] = useState<Record<number, boolean>>({});

  const biasedData: TrainingPerson[] = [
    // Historical data: 80% Group A hired, 20% Group B hired
    ...Array(16).fill(null).map(() => ({ group: 'A' as const, hired: true })),
    ...Array(4).fill(null).map(() => ({ group: 'A' as const, hired: false })),
    ...Array(4).fill(null).map(() => ({ group: 'B' as const, hired: true })),
    ...Array(16).fill(null).map(() => ({ group: 'B' as const, hired: false })),
  ];

  const balancedData: TrainingPerson[] = [
    // Balanced: 50% from each group hired
    ...Array(10).fill(null).map(() => ({ group: 'A' as const, hired: true })),
    ...Array(10).fill(null).map(() => ({ group: 'A' as const, hired: false })),
    ...Array(10).fill(null).map(() => ({ group: 'B' as const, hired: true })),
    ...Array(10).fill(null).map(() => ({ group: 'B' as const, hired: false })),
  ];

  const getDatasetStats = (type: DatasetType) => {
    const data = type === 'biased' ? biasedData : balancedData;
    const groupA = data.filter(d => d.group === 'A');
    const groupB = data.filter(d => d.group === 'B');
    const groupAHired = groupA.filter(d => d.hired).length;
    const groupBHired = groupB.filter(d => d.hired).length;
    return {
      groupATotal: groupA.length,
      groupAHired,
      groupARate: Math.round((groupAHired / groupA.length) * 100),
      groupBTotal: groupB.length,
      groupBHired,
      groupBRate: Math.round((groupBHired / groupB.length) * 100),
    };
  };

  const trainAI = () => {
    if (!dataset) return;
    setIsTraining(true);
    setShowWhy(false);

    setTimeout(() => {
      const newResults: Record<number, boolean> = {};

      testCandidates.forEach(candidate => {
        if (dataset === 'biased') {
          // Biased model: heavily favors Group A
          const baseScore = candidate.experience * 5 + candidate.skills * 0.5;
          const groupBonus = candidate.group === 'A' ? 30 : -20;
          newResults[candidate.id] = (baseScore + groupBonus) > 70;
        } else {
          // Balanced model: judges fairly on skills/experience
          const score = candidate.experience * 5 + candidate.skills * 0.5;
          newResults[candidate.id] = score > 65;
        }
      });

      setResults(newResults);

      if (dataset === 'biased') {
        setBiasedResults(newResults);
      } else {
        setBalancedResults(newResults);
      }

      setIsTraining(false);
      setIsTrained(true);
    }, 1500);
  };

  const switchDataset = (newDataset: DatasetType) => {
    setDataset(newDataset);
    setIsTrained(false);
    setShowWhy(false);
    setResults({});
  };

  const enableComparison = () => {
    setComparisonMode(true);
  };

  const reset = () => {
    setDataset(null);
    setIsTraining(false);
    setIsTrained(false);
    setResults({});
    setShowWhy(false);
    setComparisonMode(false);
    setBiasedResults({});
    setBalancedResults({});
  };

  const stats = dataset ? getDatasetStats(dataset) : null;

  return (
    <div className="app">
      <h1>Bias Detector</h1>
      <p className="intro">See how training data composition shapes AI recommendations.</p>

      {!comparisonMode ? (
        <>
          <div className="dataset-selector">
            <h3>Step 1: Choose Training Data</h3>
            <div className="dataset-options">
              <button
                className={`dataset-btn ${dataset === 'biased' ? 'selected' : ''}`}
                onClick={() => switchDataset('biased')}
              >
                <div className="dataset-title">Historical Data</div>
                <div className="dataset-desc">Based on past hiring (has bias)</div>
                <div className="dataset-preview">
                  <div className="preview-bar">
                    <div className="bar-a" style={{ width: '80%' }}></div>
                  </div>
                  <span>Group A: 80% hired</span>
                  <div className="preview-bar">
                    <div className="bar-b" style={{ width: '20%' }}></div>
                  </div>
                  <span>Group B: 20% hired</span>
                </div>
              </button>
              <button
                className={`dataset-btn ${dataset === 'balanced' ? 'selected' : ''}`}
                onClick={() => switchDataset('balanced')}
              >
                <div className="dataset-title">Balanced Sample</div>
                <div className="dataset-desc">Equal representation</div>
                <div className="dataset-preview">
                  <div className="preview-bar">
                    <div className="bar-a" style={{ width: '50%' }}></div>
                  </div>
                  <span>Group A: 50% hired</span>
                  <div className="preview-bar">
                    <div className="bar-b" style={{ width: '50%' }}></div>
                  </div>
                  <span>Group B: 50% hired</span>
                </div>
              </button>
            </div>
          </div>

          {dataset && (
            <div className="training-section">
              <h3>Step 2: Train the AI</h3>
              <div className="stats">
                <p>Training data: {stats?.groupATotal} Group A candidates ({stats?.groupARate}% hired), {stats?.groupBTotal} Group B candidates ({stats?.groupBRate}% hired)</p>
              </div>
              <button onClick={trainAI} disabled={isTraining} className="train-btn">
                {isTraining ? 'Training...' : 'Train AI'}
              </button>
              {isTraining && (
                <div className="training-animation">
                  <div className="pulse"></div>
                  <span>Learning patterns from data...</span>
                </div>
              )}
            </div>
          )}

          {isTrained && (
            <div className="results-section">
              <h3>Step 3: See Who Gets Recommended</h3>
              <div className="candidates">
                {testCandidates.map(candidate => (
                  <div key={candidate.id} className={`candidate ${results[candidate.id] ? 'recommended' : 'not-recommended'}`}>
                    <div className="candidate-info">
                      <span className="name">{candidate.name}</span>
                      <span className={`group group-${candidate.group.toLowerCase()}`}>Group {candidate.group}</span>
                    </div>
                    <div className="candidate-stats">
                      <span>{candidate.experience} yrs exp</span>
                      <span>Skills: {candidate.skills}</span>
                    </div>
                    <div className="candidate-result">
                      {results[candidate.id] ? '✓ Recommended' : '✗ Not Recommended'}
                    </div>
                  </div>
                ))}
              </div>
              <button onClick={() => setShowWhy(!showWhy)} className="why-btn">
                {showWhy ? 'Hide' : 'Show'} Why
              </button>
              {showWhy && (
                <div className="explanation">
                  {dataset === 'biased' ? (
                    <p><strong>The AI learned that Group A = more likely to be hired.</strong> This wasn't because Group A candidates are better—it's because the historical data reflected biased decisions. The AI is now perpetuating that bias.</p>
                  ) : (
                    <p><strong>The AI judges based on skills and experience.</strong> With balanced training data, the AI learned to evaluate candidates fairly, regardless of which group they belong to.</p>
                  )}
                </div>
              )}
              <button onClick={() => { switchDataset(dataset === 'biased' ? 'balanced' : 'biased'); }} className="switch-btn">
                Try {dataset === 'biased' ? 'Balanced' : 'Biased'} Data
              </button>
              {Object.keys(biasedResults).length > 0 && Object.keys(balancedResults).length > 0 && (
                <button onClick={enableComparison} className="compare-btn">Compare Both Results</button>
              )}
            </div>
          )}
        </>
      ) : (
        <div className="comparison">
          <h3>Side-by-Side Comparison</h3>
          <div className="comparison-grid">
            <div className="comparison-col">
              <h4>Biased Training Data</h4>
              {testCandidates.map(c => (
                <div key={c.id} className={`mini-candidate ${biasedResults[c.id] ? 'rec' : 'not-rec'}`}>
                  <span>{c.name} (Group {c.group})</span>
                  <span>{biasedResults[c.id] ? '✓' : '✗'}</span>
                </div>
              ))}
            </div>
            <div className="comparison-col">
              <h4>Balanced Training Data</h4>
              {testCandidates.map(c => (
                <div key={c.id} className={`mini-candidate ${balancedResults[c.id] ? 'rec' : 'not-rec'}`}>
                  <span>{c.name} (Group {c.group})</span>
                  <span>{balancedResults[c.id] ? '✓' : '✗'}</span>
                </div>
              ))}
            </div>
          </div>
          <div className="comparison-insight">
            <strong>Notice:</strong> The same candidates get different results depending on training data. Group B candidates are disadvantaged when trained on biased historical data.
          </div>
          <button onClick={reset} className="reset-btn">Start Over</button>
        </div>
      )}

      <div className="checklist">
        <h3>Bias Checklist</h3>
        <ul>
          <li>Who's overrepresented in the training data?</li>
          <li>Who's underrepresented?</li>
          <li>What historical inequities might be encoded?</li>
          <li>How will you test for disparate outcomes?</li>
        </ul>
      </div>

      <div className="reflection">
        <h3>Reflection</h3>
        <ul>
          <li>The AI isn't "biased" intentionally—so why does it produce unfair outcomes?</li>
          <li>If you only have biased historical data, what options do you have?</li>
          <li>How might you audit a real AI system for this kind of bias?</li>
        </ul>
      </div>
    </div>
  );
}

* { box-sizing: border-box; }
body { font-family: system-ui, -apple-system, sans-serif; background: #f8fafc; margin: 0; padding: 16px; }
.app { max-width: 700px; margin: 0 auto; }
h1 { font-size: 1.5rem; color: #1e293b; margin-bottom: 0.5rem; }
.intro { color: #64748b; margin-bottom: 1.5rem; font-size: 0.9rem; }

.dataset-selector { margin-bottom: 20px; }
.dataset-selector h3 { font-size: 0.9rem; color: #334155; margin-bottom: 12px; }
.dataset-options { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }
.dataset-btn { background: white; border: 2px solid #e2e8f0; border-radius: 12px; padding: 16px; text-align: left; cursor: pointer; transition: all 0.2s; }
.dataset-btn:hover { border-color: #a5b4fc; }
.dataset-btn.selected { border-color: #6366f1; background: #f5f3ff; }
.dataset-title { font-weight: 600; color: #1e293b; margin-bottom: 4px; }
.dataset-desc { font-size: 0.75rem; color: #64748b; margin-bottom: 12px; }
.dataset-preview { font-size: 0.7rem; color: #64748b; }
.preview-bar { height: 8px; background: #f1f5f9; border-radius: 4px; margin: 4px 0; overflow: hidden; }
.bar-a { height: 100%; background: #6366f1; border-radius: 4px; }
.bar-b { height: 100%; background: #f59e0b; border-radius: 4px; }

.training-section { background: white; border: 1px solid #e2e8f0; border-radius: 12px; padding: 16px; margin-bottom: 20px; }
.training-section h3 { font-size: 0.9rem; color: #334155; margin: 0 0 8px 0; }
.stats { font-size: 0.8rem; color: #64748b; margin-bottom: 12px; }
.stats p { margin: 0; }
.train-btn { background: #6366f1; color: white; border: none; padding: 10px 20px; border-radius: 8px; cursor: pointer; font-size: 0.875rem; }
.train-btn:disabled { opacity: 0.6; cursor: not-allowed; }
.training-animation { display: flex; align-items: center; gap: 12px; margin-top: 12px; color: #6366f1; font-size: 0.8rem; }
.pulse { width: 12px; height: 12px; background: #6366f1; border-radius: 50%; animation: pulse 1s infinite; }
@keyframes pulse { 0%, 100% { transform: scale(1); opacity: 1; } 50% { transform: scale(1.2); opacity: 0.7; } }

.results-section { background: white; border: 1px solid #e2e8f0; border-radius: 12px; padding: 16px; margin-bottom: 20px; }
.results-section h3 { font-size: 0.9rem; color: #334155; margin: 0 0 12px 0; }
.candidates { display: flex; flex-direction: column; gap: 8px; margin-bottom: 16px; }
.candidate { display: flex; justify-content: space-between; align-items: center; padding: 12px; border-radius: 8px; font-size: 0.8rem; }
.candidate.recommended { background: #dcfce7; border: 1px solid #86efac; }
.candidate.not-recommended { background: #fee2e2; border: 1px solid #fca5a5; }
.candidate-info { display: flex; align-items: center; gap: 8px; }
.name { font-weight: 600; color: #1e293b; }
.group { padding: 2px 8px; border-radius: 12px; font-size: 0.65rem; font-weight: 500; }
.group-a { background: #e0e7ff; color: #4338ca; }
.group-b { background: #fef3c7; color: #b45309; }
.candidate-stats { color: #64748b; font-size: 0.7rem; display: flex; gap: 12px; }
.candidate-result { font-weight: 600; }
.candidate.recommended .candidate-result { color: #16a34a; }
.candidate.not-recommended .candidate-result { color: #dc2626; }

.why-btn, .switch-btn, .compare-btn { margin-right: 8px; padding: 8px 16px; border: 1px solid #e2e8f0; background: white; border-radius: 6px; cursor: pointer; font-size: 0.8rem; }
.why-btn:hover, .switch-btn:hover, .compare-btn:hover { background: #f8fafc; }
.explanation { margin: 12px 0; padding: 12px; background: #fffbeb; border: 1px solid #fcd34d; border-radius: 8px; font-size: 0.8rem; color: #92400e; }

.comparison { background: white; border: 1px solid #e2e8f0; border-radius: 12px; padding: 16px; margin-bottom: 20px; }
.comparison h3 { font-size: 0.9rem; color: #334155; margin: 0 0 12px 0; }
.comparison-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; margin-bottom: 16px; }
.comparison-col h4 { font-size: 0.8rem; color: #64748b; margin: 0 0 8px 0; }
.mini-candidate { display: flex; justify-content: space-between; padding: 8px; border-radius: 6px; font-size: 0.75rem; margin-bottom: 4px; }
.mini-candidate.rec { background: #dcfce7; color: #166534; }
.mini-candidate.not-rec { background: #fee2e2; color: #991b1b; }
.comparison-insight { padding: 12px; background: #fef3c7; border-radius: 8px; font-size: 0.8rem; color: #92400e; margin-bottom: 12px; }
.reset-btn { background: #6366f1; color: white; border: none; padding: 10px 20px; border-radius: 8px; cursor: pointer; font-size: 0.8rem; }

.checklist { background: #fef2f2; border-radius: 12px; padding: 16px; margin-bottom: 16px; }
.checklist h3 { font-size: 0.875rem; color: #991b1b; margin: 0 0 8px 0; }
.checklist ul { margin: 0; padding-left: 20px; }
.checklist li { font-size: 0.8rem; color: #b91c1c; margin-bottom: 4px; }

.reflection { background: #f1f5f9; padding: 16px; border-radius: 12px; }
.reflection h3 { font-size: 0.875rem; color: #334155; margin: 0 0 8px 0; }
.reflection ul { margin: 0; padding-left: 20px; }
.reflection li { font-size: 0.8rem; color: #64748b; margin-bottom: 4px; }
